48. export const useCesiumComponent = <Element, Props extends RootComponentInternalProps, State = any>(
49.   {
50.     name,
51.     create,
52.     destroy,
53.     provide,
54.     update,
55.     cesiumReadonlyProps,
56.     cesiumEventProps,
57.     otherProps,
