67.   const provided = useRef<Partial<ResiumContext> | undefined>(provide ? {} : undefined);
68.   const attachedEvents = useRef<{
69.     [key in keyof Element]?: any;
70.   }>({});
71.   const initialProps = useRef<Props>(propsWithChildren(props));
72.   const prevProps = useRef<Props>({} as Props);
73.   const [mounted, setMounted] = useState(false);
74.   const mountedRef = useRef(false);
