1. import { Primitive as CesiumPrimitive } from "cesium";
2. 
3. import {
4.   ConstructorOptions,
5.   createCesiumComponent,
6.   EventProps,
7.   Merge,
8.   PickCesiumProps,
9. } from "../core";
10. 
11. /*
12. @summary
13. `Primitive` is a basic primitive in the `PrimitiveCollection`.
14. 
15. Primitive is a low layer API for geographical visualization.
16. [Entity](/components/entity) is more recommended unless performance issues.
17. */
18. 
19. /*
20. @scope
21. Inside [Viewer](/components/Viewer) or [CesiumWidget](/components/CesiumWidget) component.
22. A primitive object will be attached to the PrimitiveCollection of the Viewer or CesiumWidget.
23. */
24. 
25. export type Target = Merge<CesiumPrimitive, ConstructorOptions<typeof CesiumPrimitive>>;
26. 
27. export type PrimitiveCesiumProps = PickCesiumProps<Target, typeof cesiumProps>;
28. 
29. export type PrimitiveCesiumReadonlyProps = PickCesiumProps<Target, typeof cesiumReadonlyProps>;
30. 
31. export type PrimtiiveOtherProps = EventProps<{ id: string; primitive: CesiumPrimitive }> & {
32.   /** Calls when [Primitive#readyPromise](https://cesium.com/docs/cesiumjs-ref-doc/Primitive.html#readyPromise) is fullfilled */
33.   onReady?: (primitive: CesiumPrimitive) => void;
34. };
35. 
36. export type PrimitiveProps = PrimitiveCesiumProps &
37.   PrimitiveCesiumReadonlyProps &
38.   PrimtiiveOtherProps;
39. 
40. const cesiumProps = [
41.   "appearance",
42.   "cull",
43.   "debugShowBoundingVolume",
44.   "depthFailAppearance",
45.   "modelMatrix",
46.   "shadows",
47.   "show",
48. ] as const;
49. 
50. const cesiumReadonlyProps = [
51.   "allowPicking",
52.   "asynchronous",
53.   "compressVertices",
54.   "geometryInstances",
55.   "interleave",
56.   "releaseGeometryInstances",
57.   "vertexCacheOptimize",
58. ] as const;
59. 
60. export const otherProps = ["onReady"] as const;
61. 
62. const Primitive = createCesiumComponent<CesiumPrimitive, PrimitiveProps>({
63.   name: "Primitive",
64.   create(context, props) {
65.     if (!context.primitiveCollection) return;
66.     const element = new CesiumPrimitive(props);
67.     if (props.onReady) {
68.       element.readyPromise.then(props.onReady);
69.     }
70.     context.primitiveCollection.add(element);
71.     return element;
72.   },
73.   destroy(element, context) {
74.     if (context.primitiveCollection && !context.primitiveCollection.isDestroyed()) {
75.       context.primitiveCollection.remove(element);
76.     }
77.     if (!element.isDestroyed()) {
78.       element.destroy();
79.     }
80.   },
81.   cesiumProps,
82.   cesiumReadonlyProps,
83.   otherProps,
84.   useCommonEvent: true,
85. });
86. 
87. export default Primitive;
88.

