19. export type Options<Element, Props extends RootComponentInternalProps, State = any> = {
20.   name: string;
21.   create?: (
22.     ctx: ResiumContext,
23.     props: Props,
24.     wrapperRef: HTMLDivElement | null,
25.   ) =>
26.     | Element
27.     | [Element, State]
28.     | undefined
29.     | Promise<Element | [Element, State] | undefined>;
30.   destroy?: (
31.     element: Element,
32.     ctx: ResiumContext,
33.     wrapperRef: HTMLDivElement | null,
34.     state?: State,
35.   ) => void;
36.   provide?: (
37.     element: Element,
38.     ctx: ResiumContext,
39.     props?: Props,
40.     state?: State,
41.   ) => Partial<ResiumContext>;
42.   update?: (element: Element, props: Props, prevProps: Props, context: ResiumContext) => void;
43.   cesiumProps?: readonly (keyof Props)[];
44.   cesiumReadonlyProps?: readonly (keyof Props)[];
45.   cesiumEventProps?: EventkeyMap<Element, Props>;
46.   otherProps?: readonly (keyof Props)[];
47.   setCesiumPropsAfterCreate?: boolean;
48.   useCommonEvent?: boolean;
49.   useRootEvent?: boolean;
50. };
51. 
52. export const useCesiumComponent = <Element, Props extends RootComponentInternalProps, State = any>(
53.   {
54.     name,
55.     create,
56.     destroy,
57.     provide,
58.     update,
59.     cesiumReadonlyProps,
60.     cesiumEventProps,
61.     otherProps,
62.     setCesiumPropsAfterCreate,
63.     useCommonEvent,
64.     useRootEvent,
65.   }: Options<Element, Props, State>,
66.   props: Props,
67.   ref: any,
68. ): [Partial<ResiumContext> | undefined, boolean, RefObject<HTMLDivElement>] => {
69.   const element = useRef<Element>();
70.   const ctx = useCesium();
71.   const provided = useRef<Partial<ResiumContext> | undefined>(provide ? {} : undefined);
72.   const attachedEvents = useRef<{
73.     [key in keyof Element]?: any;
74.   }>({});
75.   const initialProps = useRef<Props>(propsWithChildren(props));
76.   const prevProps = useRef<Props>({} as Props);
77.   const [mounted, setMounted] = useState(false);
78.   const mountedRef = useRef(false);
79.   const wrapperRef = useRef<HTMLDivElement>(null);
80.   const stateRef = useRef<State>();
81.   const mountIdRef = useRef(0);
82.   const eventManager = ctx?.[eventManagerContextKey];
83. 
84.   // Update properties
85.   const updateProperties = useCallback(
86.     (props: Props) => {
87.       if (!element.current) return;
88.       const target: any = element.current;
89. 
90.       const propsKeys = Object.keys(props) as (keyof Props)[];
91.       const eventKeys = Object.keys(cesiumEventProps || []) as (keyof Props)[];
92. 
93.       const propDiff = propsKeys
94.         .concat(
95.           (Object.keys(prevProps.current) as (keyof Props)[]).filter(k => !propsKeys.includes(k)),
96.         )
97.         .filter(k => prevProps.current[k] !== props[k])
98.         .map(k => [k, prevProps.current[k], props[k]] as [keyof Props, any, any]);
99. 
100.       const updatedReadonlyProps: (keyof Props)[] = [];
101.       for (const [k, prevValue, newValue] of propDiff) {
102.         if (cesiumReadonlyProps?.includes(k)) {
103.           updatedReadonlyProps.push(k);
104.         } else if (includes(eventKeys, k)) {
105.           const cesiumKey = cesiumEventProps?.[k] as keyof Element;
106.           const eventHandler = target[cesiumKey];
107.           if (eventHandler instanceof CesiumEvent) {
108.             if (typeof prevValue === "undefined") {
109.               // added
110.               eventHandler.addEventListener(newValue);
111.               attachedEvents.current[cesiumKey] = newValue;
112.             } else if (typeof newValue === "undefined") {
113.               // deleted
114.               eventHandler.removeEventListener(prevValue);
115.               delete attachedEvents.current[cesiumKey];
116.             } else {
117.               // updated
118.               eventHandler.removeEventListener(prevValue);
119.               eventHandler.addEventListener(newValue);
120.             }
121.           }
122.         } else if (k !== "children" && !eventNames.includes(k as any) && !otherProps?.includes(k)) {
123.           target[k] = newValue;
124.         }
125.       }
126. 
127.       const em = useRootEvent
128.         ? (provided.current?.[eventManagerContextKey] as EventManager | undefined)
129.         : eventManager;
130.       if (useCommonEvent && em && element.current) {
131.         em.setEvents(useRootEvent ? null : element.current, props);
132.       }
133. 
134.       if (update && mountedRef.current) {
135.         update(element.current, props, prevProps.current, ctx);
136.       }
137. 
138.       prevProps.current = props;
139.       initialProps.current = props;
140. 
141.       // Recreate cesium element when any read-only prop is updated
142.       if (mountedRef.current && updatedReadonlyProps.length > 0) {
143.         if (process.env.NODE_ENV !== "production") {
144.           console.warn(
145.             `Warning: <${name}> is recreated because following read-only props have been updated: ${updatedReadonlyProps.join(
146.               ", ",
147.             )}`,
148.           );
149.         }
150. 
151.         unmount();
152.         mount();
153.       }
154.     },
155.     [], // eslint-disable-line react-hooks/exhaustive-deps
156.   );
157. 
158.   const mount = useCallback(() => {
159.     const mountId = ++mountIdRef.current;
160. 
161.     const setElement = (result: Element | [Element, State] | undefined) => {
162.       if (mountId !== mountIdRef.current) return;
163. 
164.       // Initialize cesium element
165.       if (Array.isArray(result)) {
166.         element.current = result[0];
167.         stateRef.current = result[1];
168.       } else {
169.         element.current = result;
170.       }
171. 
172.       if (setCesiumPropsAfterCreate) {
173.         updateProperties(initialProps.current);
174.       } else {
175.         // Attach events
176.         if (element.current && cesiumEventProps) {
177.           const target: any = element.current;
178.           for (const key of Object.keys(initialProps.current) as (keyof Props)[]) {
179.             const eventKey = cesiumEventProps[key];
180.             if (eventKey) {
181.               const e: any = initialProps.current[key];
182.               const eventHandler = target[eventKey];
183.               if (e && eventHandler instanceof CesiumEvent) {
184.                 eventHandler.addEventListener(e);
185.               }
186.             }
187.           }
188.         }
189. 
190.         prevProps.current = initialProps.current;
191.       }
192. 
193.       if (provide && element.current) {
194.         provided.current = {
195.           ...ctx,
196.           ...provide(element.current, ctx, props, stateRef.current),
197.         };
198.       }
199. 
200.       const em = useRootEvent
201.         ? (provided.current?.[eventManagerContextKey] as EventManager | undefined)
202.         : eventManager;
203.       if (useCommonEvent && em && element.current) {
204.         em.setEvents(useRootEvent ? null : element.current, initialProps.current);
205.       }
206. 
207.       if (element.current) {
208.         setMounted(true);
209.         mountedRef.current = true;
210.       }
211.     };
212. 
213.     const result = create?.(ctx, initialProps.current, wrapperRef.current);
214.     if (result && typeof (result as Promise<Element>).then === "function") {
