1. import { render, screen } from "@testing-library/react";
2. import { Event } from "cesium";
3. import { createRef, ReactNode } from "react";
4. import { beforeEach, describe, expect, it, vi, vitest } from "vitest";
5. 
6. import { createCesiumComponent, CesiumComponentRef } from "./component";
7. import { Provider } from "./context";
8. 
9. beforeEach(() => {
10.   console.warn = vi.fn();
11. });
12. 
13. describe("core/component", () => {
14.   it("should create and expose cesium element correctly on initialized", () => {
15.     const create = vi.fn(() => "foobar");
16.     const value = { hoge: 1 } as any;
17. 
18.     const Component = createCesiumComponent<string, { test: number }>({
19.       name: "test",
20.       create,
21.     });
22. 
23.     const ref = createRef<CesiumComponentRef<string>>();
24. 
25.     render(
26.       <Provider value={value}>
27.         <Component test={1} ref={ref} />
28.       </Provider>,
29.     );
30. 
31.     expect(create).toBeCalledWith(value, { test: 1 }, null);
32.     expect(create).toBeCalledTimes(1);
33.     expect(ref.current?.cesiumElement).toBe("foobar");
34.   });
35. 
36.   it("should call destroy fn on unmounted", () => {
37.     const destroy = vi.fn();
38.     const value = { hoge: 1 } as any;
39. 
40.     const Component = createCesiumComponent<string, { test: number }>({
41.       name: "test",
42.       create: () => "foobar",
43.       destroy,
44.     });
45. 
46.     render(
47.       <Provider value={value}>
48.         <Component test={1} />
49.       </Provider>,
50.     ).unmount();
51. 
52.     expect(destroy).toBeCalledWith("foobar", value, null, undefined);
53.     expect(destroy).toBeCalledTimes(1);
54.   });
55. 
56.   it("should set cesium events after created", () => {
57.     const cesiumElement = {
58.       hoge: new Event(),
59.     };
60. 
61.     const Component = createCesiumComponent<typeof cesiumElement, { bar?: () => void }>({
62.       name: "test",
63.       create: () => cesiumElement,
64.       cesiumEventProps: { bar: "hoge" },
65.     });
66. 
67.     render(<Component bar={() => {}} />);
68. 
69.     expect(cesiumElement.hoge.numberOfListeners).toBe(1);
70.   });
71. 
72.   it("should set cesium props after created", () => {
73.     const cesiumElement = {
74.       foo: 0,
75.     };
76. 
77.     const Component = createCesiumComponent<typeof cesiumElement, { foo?: number }>({
78.       name: "test",
79.       create: () => cesiumElement,
80.       cesiumProps: ["foo"],
81.       setCesiumPropsAfterCreate: true,
82.     });
83. 
84.     render(<Component foo={10} />);
85. 
86.     expect(cesiumElement.foo).toBe(10);
87.   });
88. 
89.   it("should update cesium props", () => {
90.     const cesiumElement = {
91.       foo: 0,
92.     };
93. 
94.     const Component = createCesiumComponent<typeof cesiumElement, { foo?: number }>({
95.       name: "test",
96.       create: () => cesiumElement,
97.       cesiumProps: ["foo"],
98.     });
99. 
100.     const { rerender } = render(<Component />);
101. 
102.     expect(cesiumElement.foo).toBe(0);
103. 
104.     rerender(<Component foo={1} />);
105. 
106.     expect(cesiumElement.foo).toBe(1);
107.   });
108. 
109.   it("should update cesium events", () => {
110.     const cesiumElement = {
111.       foo: new Event(),
112.       bar: new Event(),
113.       hoge: new Event(),
114.     };
115. 
116.     const Component = createCesiumComponent<
117.       typeof cesiumElement,
118.       { foo?: () => void; bar?: () => void; hoge?: () => void }
119.     >({
120.       name: "test",
121.       create: () => cesiumElement,
122.       cesiumEventProps: {
123.         foo: "foo",
124.         bar: "bar",
125.         hoge: "hoge",
126.       },
127.     });
128. 
129.     const { rerender } = render(<Component foo={() => {}} hoge={() => {}} />);
130. 
131.     expect(cesiumElement.foo.numberOfListeners).toBe(1);
132.     expect(cesiumElement.bar.numberOfListeners).toBe(0);
133.     expect(cesiumElement.hoge.numberOfListeners).toBe(1);
134. 
135.     rerender(<Component bar={() => {}} hoge={() => {}} />);
136. 
137.     expect(cesiumElement.foo.numberOfListeners).toBe(0);
138.     expect(cesiumElement.bar.numberOfListeners).toBe(1);
139.     expect(cesiumElement.hoge.numberOfListeners).toBe(1); // TODO
140.   });
141. 
142.   it("should remount when cesium read only props are updated", () => {
143.     const cesiumElement = {
144.       foo: 0,
145.     };
146. 
147.     const createFn = vi.fn((_ctx, props: { foo?: number }) => {
148.       if (typeof props.foo === "number") {
149.         cesiumElement.foo = props.foo;
150.       }
151.       return cesiumElement;
152.     });
153.     const destroyFn = vi.fn();
154. 
155.     const Component = createCesiumComponent<typeof cesiumElement, { foo?: number }>({
156.       name: "test",
157.       create: createFn,
158.       destroy: destroyFn,
159.       cesiumReadonlyProps: ["foo"],
160.     });
161. 
162.     const { rerender } = render(<Component foo={1} />);
163. 
164.     expect(createFn).toBeCalledTimes(1);
165.     expect(destroyFn).toBeCalledTimes(0);
166.     expect(cesiumElement.foo).toBe(1);
167. 
168.     rerender(<Component foo={2} />);
169. 
170.     expect(createFn).toBeCalledTimes(2);
171.     expect(destroyFn).toBeCalledTimes(1);
172.     expect(cesiumElement.foo).toBe(2);
173.   });
174. 
175.   it("should call update", () => {
176.     const updateFn = vi.fn();
177. 
178.     const Component = createCesiumComponent<{ hoge: "hoge" }, { foo?: number }>({
179.       name: "test",
180.       create: () => ({ hoge: "hoge" }),
181.       update: updateFn,
182.     });
183. 
184.     const { rerender } = render(<Component />);
185. 
186.     expect(updateFn).toBeCalledTimes(0);
187. 
188.     rerender(<Component foo={1} />);
189. 
190.     expect(updateFn).toBeCalledTimes(1);
191.     expect(updateFn).toBeCalledWith({ hoge: "hoge", foo: 1 }, { foo: 1 }, {}, {});
192.   });
193. 
194.   it("should provide context", () => {
195.     const create1 = vi.fn(() => "test");
196.     const create2 = vi.fn(() => "test");
197. 
198.     const Component1 = createCesiumComponent<string, { children?: ReactNode }>({
199.       name: "test",
200.       create: create1,
201.       provide: (): any => ({ context: "b" }),
202.     });
203. 
204.     const Component2 = createCesiumComponent<string, {}>({
205.       name: "test2",
206.       create: create2,
207.     });
208. 
209.     render(
210.       <Provider value={{ context: "a", context2: "foo" } as any}>
211.         <Component1>
212.           <Component2 />
213.         </Component1>
214.       </Provider>,
215.     );
216. 
217.     expect(create1).toBeCalledWith({ context: "a", context2: "foo" }, expect.anything(), null);
218.     expect(create2).toBeCalledWith({ context: "b", context2: "foo" }, expect.anything(), null);
219.   });
220. 
221.   it("should invoke onUpdate event when being dirty", () => {
222.     const cesiumElement = {
223.       foo: 0,
224.     };
225.     const onUpdate = vitest.fn();
226. 
227.     const Component = createCesiumComponent<typeof cesiumElement, { foo?: number }>({
228.       name: "test",
229.       create: () => cesiumElement,
230.       cesiumProps: ["foo"],
231.     });
232. 
233.     const { rerender } = render(
234.       <Provider
235.         value={{
236.           __$internal: {
237.             onUpdate,
238.           },
239.         }}>
240.         <Component />
241.       </Provider>,
242.     );
243. 
244.     expect(cesiumElement.foo).toBe(0);
245.     expect(onUpdate).not.toBeCalled();
246. 
247.     rerender(
248.       <Provider
249.         value={{
250.           __$internal: {
251.             onUpdate,
252.           },
253.         }}>
254.         <Component foo={1} />
255.       </Provider>,
256.     );
257. 
258.     expect(cesiumElement.foo).toBe(1);
259.     expect(onUpdate).toBeCalledTimes(1);
260.   });
261. 
262.   it("should render container", () => {
263.     const createFn = vi.fn(() => "foobar");
264. 
265.     const Component = createCesiumComponent<string, { className?: string }>({
266.       name: "test",
267.       create: createFn,
268.       renderContainer: true,
269.       containerProps: ["className"],
270.     });
271. 
272.     render(
273.       <Provider value={{}}>
274.         <Component className="hoge" />
275.       </Provider>,
276.     );
277. 
278.     expect(createFn).toBeCalledWith(
279.       expect.anything(),
280.       expect.anything(),
281.       expect.any(HTMLDivElement),
282.     );
283.     const containers = screen.getAllByTestId("resium-container");
284.     expect(containers.length).toBe(1);
285.     expect(containers[0].getAttribute("class")).toBe("hoge");
286.   });
287. 
288.   it("should keep state", () => {
289.     const provideFn = vi.fn();
290.     const destroyFn = vi.fn();
291. 
292.     const state = {};
293. 
294.     const Component = createCesiumComponent<string, {}>({
295.       name: "test",
296.       create: () => ["foobar", state],
297.       provide: provideFn,
298.       destroy: destroyFn,
299.     });
300. 
301.     render(
302.       <Provider value={{}}>
303.         <Component />
304.       </Provider>,
305.     ).unmount();
306. 
307.     expect(provideFn).toBeCalledWith(
308.       expect.anything(),
309.       expect.anything(),
310.       expect.anything(),
311.       state,
312.     );
313.     expect(destroyFn).toBeCalledWith(expect.anything(), expect.anything(), null, state);
314.   });
315. 
316.   it("should not render when noChildren is true", () => {
317.     const Component = createCesiumComponent<string, { children?: ReactNode }>({
318.       name: "test",
319.       noChildren: false,
320.     });
321. 
322.     const { rerender } = render(
323.       <Component>
324.         <p data-testid="hello">Hello!</p>
325.       </Component>,
326.     );
327. 
328.     expect(screen.getByTestId("hello")).toBeInTheDocument();
329. 
330.     const Component2 = createCesiumComponent<string, { children?: ReactNode }>({
331.       name: "test",
332.       noChildren: true,
333.     });
334. 
335.     rerender(
336.       <Component2>
337.         <p data-testid="hello">Hello!</p>
338.       </Component2>,
339.     );
340. 
341.     expect(screen.queryByTestId("hello")).not.toBeInTheDocument();
342.   });
343. });
